CREATE TABLE CW_INVOICE_SEQUENCE (SERIES_KEY VARCHAR(20) NOT NULL, SEQUENCE_YEAR INTEGER NOT NULL, NEXT_VALUE BIGINT NOT NULL, PRIMARY KEY (SERIES_KEY, SEQUENCE_YEAR));
CREATE TABLE CW_INVOICE (ID BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY, STATUS VARCHAR(20) NOT NULL, INVOICE_NUMBER VARCHAR(64) UNIQUE, NUMBER_SERIES VARCHAR(20), ISSUE_DATE DATE, SERVICE_DATE DATE NOT NULL, CURRENCY CHAR(3) NOT NULL, SELLER_NAME VARCHAR(255) NOT NULL, SELLER_ADDRESS VARCHAR(2000) NOT NULL, SELLER_TAX_ID VARCHAR(64) NOT NULL, CUSTOMER_NAME VARCHAR(255) NOT NULL, CUSTOMER_ADDRESS VARCHAR(2000) NOT NULL, PAYMENT_TERMS VARCHAR(2000) NOT NULL, NET_TOTAL DECIMAL(19,2) NOT NULL, TAX_TOTAL DECIMAL(19,2) NOT NULL, GROSS_TOTAL DECIMAL(19,2) NOT NULL, CREATED_AT TIMESTAMP NOT NULL, FINALIZED_AT TIMESTAMP, CONSTRAINT CW_INV_STATUS CHECK (STATUS IN ('DRAFT','FINALIZED','CANCELLED')));
CREATE TABLE CW_INVOICE_LINE (INVOICE_ID BIGINT NOT NULL, LINE_NO INTEGER NOT NULL, DESCRIPTION VARCHAR(2000) NOT NULL, QUANTITY DECIMAL(19,4) NOT NULL, UNIT_NET DECIMAL(19,4) NOT NULL, TAX_RATE DECIMAL(7,4) NOT NULL, NET_AMOUNT DECIMAL(19,2) NOT NULL, TAX_AMOUNT DECIMAL(19,2) NOT NULL, GROSS_AMOUNT DECIMAL(19,2) NOT NULL, PRIMARY KEY (INVOICE_ID, LINE_NO), CONSTRAINT CW_INV_LINE_FK FOREIGN KEY (INVOICE_ID) REFERENCES CW_INVOICE(ID));

